// Stand-in for the parts of `ide-host` that the code generated by `#[command]`, `domain!` and
// `domains!` names; doctests `include!` it at their crate root.

pub type IdeResult<T> = Result<T, IdeError>;

#[derive(Debug)]
pub struct IdeError(pub String);

impl IdeError {
    pub fn unavailable(m: impl Into<String>) -> Self {
        Self(m.into())
    }
}

pub struct Host;

impl Host {
    pub fn plugin_host(&self) -> Option<std::sync::Arc<plugins::PluginHost>> {
        None
    }
}

pub mod plugins {
    pub struct PluginHost;
}

pub mod catalogue {
    #[derive(Clone, Copy, Debug, PartialEq, Eq)]
    pub enum TrustClass {
        Always,
        OutsideRestricted,
        Trusted,
    }
    #[derive(Clone, Copy, Debug, PartialEq, Eq)]
    pub enum Placement {
        Desktop,
        ProjectHost,
    }
    #[derive(Clone, Copy, Debug, PartialEq, Eq)]
    pub enum Mode {
        Sync,
        Async,
        Spawn,
    }
    #[derive(Clone, Copy, Debug, PartialEq, Eq)]
    pub struct Command {
        pub name: &'static str,
        pub trust: TrustClass,
        pub placement: Placement,
        pub bindings: bool,
        pub mode: Mode,
    }
}

pub mod ops {
    pub struct Channel<T>(pub std::marker::PhantomData<T>);
    pub type Emit<T> = std::sync::Arc<dyn Fn(T) + Send + Sync>;
}

pub mod rpc {
    use crate::catalogue::TrustClass;
    use crate::{IdeResult, ops::Channel};

    pub struct Call {
        pub host: std::sync::Arc<crate::Host>,
        pub window: String,
    }

    impl Call {
        pub fn arg<T: Default>(&self, _name: &str) -> IdeResult<T> {
            Ok(T::default())
        }
        pub fn sender<T>(&self, _name: &str) -> IdeResult<Channel<T>> {
            Ok(Channel(std::marker::PhantomData))
        }
    }

    #[derive(Default)]
    pub struct Dispatcher(pub Vec<(&'static str, TrustClass)>);

    impl Dispatcher {
        pub fn add<F, Fut, T>(&mut self, name: &'static str, trust: TrustClass, _f: F) -> &mut Self
        where
            F: Fn(Call) -> Fut + Send + Sync + 'static,
            Fut: Future<Output = IdeResult<T>> + Send + 'static,
            T: serde::Serialize,
        {
            self.0.push((name, trust));
            self
        }
    }
}
